package scaffold

import (
	"fmt"
	"go/format"
	"sort"
	"strings"

	"github.com/jamestryand/pocketcqrs/edges"
)

// GoEdgesFile is the generated file holding a system's edge tables, beside
// the wiring (GoWiringFile).
const GoEdgesFile = "edges.go"

// GenerateGoEdges writes a system's edges from a coordinating document as two
// tables in the wiring package: EdgesIn (the internal edges into it, each
// translated by edges.In.Translate) and EdgesOut (the public events it
// publishes for edges out of it, each by edges.Publish). Data only: what they
// mean is package edges, so the tables cannot carry logic of their own. No
// carrier is named; the host passes them to one.
func GenerateGoEdges(pkg, architecture, system string, ins []edges.In, outs []edges.Out) (string, error) {
	if !goIdent.MatchString(pkg) {
		return "", fmt.Errorf("edges package name %q is not a Go identifier", pkg)
	}
	var b strings.Builder
	fmt.Fprintf(&b, "// Code generated by pocketcqrs schema import; DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package %s\n\n", pkg)
	fmt.Fprintf(&b, "import \"github.com/jamestryand/pocketcqrs/edges\"\n\n")
	fmt.Fprintf(&b, "// EdgesSystem is this system's id in the coordinating document %q.\n", architecture)
	fmt.Fprintf(&b, "const EdgesSystem = %q\n\n", system)
	fmt.Fprintf(&b, "// EdgesIn are the internal edges into this system: give each message a carrier\n")
	fmt.Fprintf(&b, "// delivers to edges.Find, and send what edges.In.Translate makes of it.\n")
	fmt.Fprintf(&b, "var EdgesIn = []edges.In{\n")
	for _, e := range ins {
		keys := make([]string, 0, len(e.Fields))
		for k := range e.Fields {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		fmt.Fprintf(&b, "\t{ID: %q, FromSystem: %q, FromEvent: %q, FromVersion: %d,\n", e.ID, e.FromSystem, e.FromEvent, e.FromVersion)
		fmt.Fprintf(&b, "\t\tAggregate: %q, Command: %q, TargetField: %q,\n", e.Aggregate, e.Command, e.TargetField)
		fmt.Fprintf(&b, "\t\tFields: map[string]string{")
		for i, k := range keys {
			if i > 0 {
				b.WriteString(", ")
			}
			fmt.Fprintf(&b, "%q: %q", k, e.Fields[k])
		}
		fmt.Fprintf(&b, "}},\n")
	}
	fmt.Fprintf(&b, "}\n\n")
	fmt.Fprintf(&b, "// EdgesOut are the public events this system publishes for internal edges out of\n")
	fmt.Fprintf(&b, "// it, each with only the fields some edge maps: pass each committed event to\n")
	fmt.Fprintf(&b, "// edges.Publish, and send the message it makes.\n")
	fmt.Fprintf(&b, "var EdgesOut = []edges.Out{\n")
	for _, o := range outs {
		quoted := make([]string, len(o.Fields))
		for i, f := range o.Fields {
			quoted[i] = fmt.Sprintf("%q", f)
		}
		fmt.Fprintf(&b, "\t{EventType: %q, System: %q, Event: %q, Version: %d, Fields: []string{%s}},\n",
			o.EventType, o.System, o.Event, o.Version, strings.Join(quoted, ", "))
	}
	fmt.Fprintf(&b, "}\n")
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return "", fmt.Errorf("generated edges do not format: %w", err)
	}
	return string(src), nil
}
